/**
 * Derives a studio display name from the user's full name.
 * e.g. "Alex Rivera" → "Alex Rivera Tattoo"
 * Only used when the studio name is still the signup default "My Studio".
 */
export function autoStudioName(fullName: string): string {
  const trimmed = fullName.trim()
  if (!trimmed) return 'My Studio'
  return `${trimmed} Tattoo`
}

