  it('rejects single-space fullName', () => {
    const result = personaPickerSchema.safeParse({ ...base, fullName: ' ' })
    expect(result.success).toBe(false)
  })

  it('trims surrounding whitespace before length check', () => {
    // "  A  " trims to "A" (length 1) — should fail min(2)
    const result = personaPickerSchema.safeParse({ ...base, fullName: '  A  ' })
    expect(result.success).toBe(false)
    // "  AB  " trims to "AB" (length 2) — should pass
    const ok = personaPickerSchema.safeParse({ ...base, fullName: '  AB  ' })
    expect(ok.success).toBe(true)
  })
})

