import { describe, expect, it } from 'vitest'
import { autoStudioName } from '@/lib/onboarding/persona'

describe('autoStudioName', () => {
  it('appends "Tattoo" to a normal full name', () => {
    expect(autoStudioName('Alex Rivera')).toBe('Alex Rivera Tattoo')
  })

  it('returns "My Studio" for an empty string', () => {
    expect(autoStudioName('')).toBe('My Studio')
  })

  it('returns "My Studio" for a whitespace-only string', () => {
    expect(autoStudioName('   ')).toBe('My Studio')
  })

  it('trims surrounding whitespace before appending "Tattoo"', () => {
    expect(autoStudioName('  Sam Lee  ')).toBe('Sam Lee Tattoo')
  })
})

import { expect, test } from '@playwright/test'

/**
 * E2E: Onboarding persona picker
 *
 * Runs against the Railway preview URL (PLAYWRIGHT_BASE_URL env var).
 * These tests require a signed-in session that has NOT yet completed
 * onboarding — use the demo seed "demo-new@inkos.com" / "Demo123!Aa"
 * account (seeded in its un-onboarded state for CI).
 *
 * All selectors are derived from PersonaPicker.tsx — update both if the
 * component changes.
 */

const DEMO_EMAIL = 'demo-new@inkos.com'
const DEMO_PASSWORD = 'Demo123!Aa'

async function loginAndGoToOnboarding(page: Parameters<Parameters<typeof test>[1]>[0]['page']) {
  await page.goto('/login')
  await page.getByLabel(/email/i).fill(DEMO_EMAIL)
  await page.getByLabel(/password/i).fill(DEMO_PASSWORD)
  await page.getByRole('button', { name: /sign in/i }).click()
  // After login the middleware should redirect unonboarded users to /onboarding
  await page.waitForURL('**/onboarding', { timeout: 10_000 })
}

// ─── Layout & copy ────────────────────────────────────────────────────────────

test('onboarding page shows correct title', async ({ page }) => {
  await loginAndGoToOnboarding(page)
  await expect(page.getByRole('heading', { name: 'How do you use InkOS?' })).toBeVisible()
})

test('onboarding page shows both persona cards', async ({ page }) => {
  await loginAndGoToOnboarding(page)
  await expect(page.getByRole('radio', { name: /solo artist/i })).toBeVisible()
  await expect(page.getByRole('radio', { name: /studio owner/i })).toBeVisible()
})

test('submit button reads "Open the studio"', async ({ page }) => {
  await loginAndGoToOnboarding(page)
  await expect(page.getByRole('button', { name: 'Open the studio' })).toBeVisible()
})

// ─── Validation ───────────────────────────────────────────────────────────────

test('submitting without selecting a persona shows error', async ({ page }) => {
  await loginAndGoToOnboarding(page)
  await page.getByLabel(/your name/i).fill('Alex Rivera')
  await page.getByRole('button', { name: 'Open the studio' }).click()
  await expect(page.getByRole('alert')).toContainText(/select how you use InkOS/i)
})

test('submitting with whitespace-only name shows error', async ({ page }) => {
  await loginAndGoToOnboarding(page)
  await page.getByRole('radio', { name: /solo artist/i }).click()
  await page.getByLabel(/your name/i).fill('   ')
  await page.getByRole('button', { name: 'Open the studio' }).click()
  await expect(page.getByRole('alert')).toContainText(/at least 2 characters/i)
})

// ─── Happy path ───────────────────────────────────────────────────────────────

test('selecting solo artist and submitting redirects to /dashboard', async ({ page }) => {
  await loginAndGoToOnboarding(page)
  await page.getByRole('radio', { name: /solo artist/i }).click()
  // Verify selected state via aria-checked
  await expect(page.getByRole('radio', { name: /solo artist/i })).toHaveAttribute('aria-checked', 'true')
  await page.getByLabel(/your name/i).fill('Alex Rivera')
  await page.getByRole('button', { name: 'Open the studio' }).click()
  await page.waitForURL('**/dashboard', { timeout: 15_000 })
  await expect(page).toHaveURL(/\/dashboard/)
})

test('selecting studio owner and submitting redirects to /dashboard', async ({ page }) => {
  await loginAndGoToOnboarding(page)
  await page.getByRole('radio', { name: /studio owner/i }).click()
  await expect(page.getByRole('radio', { name: /studio owner/i })).toHaveAttribute('aria-checked', 'true')
  await page.getByLabel(/your name/i).fill('Jordan Lee')
  await page.getByRole('button', { name: 'Open the studio' }).click()
  await page.waitForURL('**/dashboard', { timeout: 15_000 })
  await expect(page).toHaveURL(/\/dashboard/)
})

// ─── Keyboard navigation ──────────────────────────────────────────────────────

test('arrow keys navigate between persona cards', async ({ page }) => {
  await loginAndGoToOnboarding(page)
  // Focus first card then arrow down to second
  const soloCard = page.getByRole('radio', { name: /solo artist/i })
  await soloCard.focus()
  await page.keyboard.press('ArrowRight')
  await expect(page.getByRole('radio', { name: /studio owner/i })).toBeFocused()
})
